(function(){
"use strict";
const S=window.WHYStore,E=window.WHYEngine,CASES=window.WHY_SCENARIOS;
const $=id=>document.getElementById(id);
const esc=x=>String(x??"").replace(/[&<>"']/g,c=>({"&":"&amp;","<":"&lt;",">":"&gt;",'"':"&quot;","'":"&#39;"}[c]));
const labels={draft:"候補",selected:"自分で選んだ",held:"保留",paused:"休止",completed:"実施",undecided:"未定",exploring:"探索中",confirmed:"本人確認済み","unclassified":"未分類","user-reported-fact":"本人が述べた事実（外部未確認）",feeling:"本人の気持ち",value:"本人の価値観・希望",interpretation:"本人の解釈",prediction:"本人の予測"};
let intendedFocus=null,editOrigin=null,pendingPlanSource=null,pendingAspirationSource=null;
const variant=new URLSearchParams(location.search).get("variant")==="curiosity"?"curiosity":"readable";document.documentElement.dataset.variant=variant;
let state=S.empty(),suggestion=null,pendingImport=null,beforeImport=null,beforeDelete=null,toastTimer=null;
function toast(text){$("toast").textContent=text;$("toast").classList.add("visible");clearTimeout(toastTimer);toastTimer=setTimeout(()=>$("toast").classList.remove("visible"),7000);}
function storageError(text){$("storage-error-text").textContent=text;$("storage-error").hidden=false;}
$("dismiss-storage-error").addEventListener("click",()=>{$("storage-error").hidden=true;});
function current(){return state.sessions[state.sessions.length-1];}
let activeOwner="guest",revisionCounter=0;const workspaces=new Map();
function storage(){const raw=window.localStorage;const scoped=k=>k+"-"+activeOwner;return{getItem:k=>raw.getItem(scoped(k)),setItem:(k,v)=>raw.setItem(scoped(k),v),removeItem:k=>raw.removeItem(scoped(k))};}
try{const loaded=S.load(storage());if(loaded.ok&&loaded.state&&loaded.state.preferences.persist){state=loaded.state;toast("このブラウザーに保存したWHY試作データを復元しました。");}else if(!loaded.ok)storageError(loaded.error);}catch(e){storageError("ブラウザー保存は利用できません。画面内の操作とJSON書き出しを利用できます。");}
function invalidateUndo(){beforeImport=null;beforeDelete=null;$("undo-import").disabled=true;$("undo-delete").disabled=true;}
function commit(keepUndo=false){revisionCounter++;window.dispatchEvent(new CustomEvent("why-data-changed"));if(!keepUndo)invalidateUndo();if(state.preferences.persist){try{const r=S.save(state,storage());if(!r.ok){state.preferences.persist=false;storageError(r.error);}}catch(e){state.preferences.persist=false;storageError("保存できません。入力は画面内に残っています。JSONに書き出してください。");}}render();}
function route(options){const initialEmbedded=options===true&&window.self!==window.top;const valid=["home","dialogue","aspirations","plans","experiences","memory"];let name=location.hash.slice(1)||"home";if(!valid.includes(name)){name="home";history.replaceState(null,"","#home");}document.querySelectorAll(".screen").forEach(s=>s.hidden=s.id!=="screen-"+name);document.querySelectorAll("[data-route]").forEach(a=>{if(a.dataset.route===name)a.setAttribute("aria-current","page");else a.removeAttribute("aria-current");});const heading=document.querySelector("#screen-"+name+" h1");heading.tabIndex=-1;document.title=heading.textContent+"｜S.u.G WHY ページ候補";$("nav-toggle").setAttribute("aria-expanded","false");document.documentElement.dataset.nav="closed";const target=intendedFocus?$(intendedFocus):heading;intendedFocus=null;if(initialEmbedded)return;(target&&!target.disabled?target:heading).focus({preventScroll:true});window.scrollTo({top:0,behavior:"instant"});}
window.addEventListener("hashchange",route);
document.querySelector(".skip").addEventListener("click",e=>{e.preventDefault();$("main").focus();});
$("nav-toggle").addEventListener("click",()=>{const open=$("nav-toggle").getAttribute("aria-expanded")!=="true";$("nav-toggle").setAttribute("aria-expanded",String(open));document.documentElement.dataset.nav=open?"open":"closed";});
$("text-scale").addEventListener("change",()=>document.documentElement.dataset.textScale=$("text-scale").value);
$("reduce-motion").addEventListener("change",()=>document.documentElement.dataset.motion=$("reduce-motion").checked?"reduce":"auto");
function go(name){if(location.hash==="#"+name)route();else location.hash=name;}
function render(){
const se=current();const messages=se?state.messages.filter(m=>m.sessionId===se.id):[];
$("chat-log").innerHTML=messages.length?messages.map(m=>'<div class="chat-message '+esc(m.role)+' '+esc(m.status)+'"><div class="chat-label">'+(m.role==="user"?"あなた":"COACH")+'</div><div class="body"><p>'+esc(m.text)+'</p>'+(m.status!=="current"?'<span class="badge">'+(m.status==="superseded"?"訂正済み":"取下げ済み")+'</span>':"")+(m.role==="user"&&m.status==="current"?'<button type="button" class="link-button" data-action="edit-message" data-id="'+esc(m.id)+'">この発言を訂正</button>':"")+'</div></div>').join(""):'<p class="empty">疑問も、まだ言葉にならないことも。ここから話せます。</p>';
const ended=se&&se.status==="ended";$("chat-input").disabled=!!ended;$("send-chat").disabled=!!ended;$("end-chat").disabled=!!ended;$("hold-chat").disabled=!!ended;$("session-status").textContent=ended?"この会話は終了しました。「新しく話す」で再開できます。":se&&!se.adviceAllowed?"助言・行動提案をしない希望を反映中。":"模擬対話。未対応の内容は推測で補いません。";
$("suggestion").hidden=!suggestion||!!ended||!se?.adviceAllowed;if(suggestion)$("suggestion-text").textContent="検討候補："+suggestion.title;
const plans=state.plans.filter(x=>!x.deleted);$("home-next").textContent=plans.length?plans[plans.length-1].title+" — "+labels[plans[plans.length-1].status]:"まだ何も決めていなくていい。";
$("aspiration-list").innerHTML=list(state.aspirations,"aspiration",x=>'<p class="meta">'+esc(labels[x.status])+'</p><p>'+esc(x.text)+'</p>');
$("plan-list").innerHTML=list(state.plans,"plan",x=>'<p class="meta">'+esc(labels[x.status])+(x.needsReview?' <span class="needs-review">発言・目的の変更により要見直し</span>':"")+'</p><h3>'+esc(x.title)+'</h3><p>'+esc(x.reason||"理由は未記入")+'</p><p class="quiet">いつ：'+esc(x.when||"未定")+' / 量：'+esc(x.amount||"未定")+'</p><p class="quiet">予想：'+esc(x.prediction||"未記入")+'<br>確かめること：'+esc(x.observe||"未記入")+'</p><div class="record-actions"><button type="button" data-action="hold-plan" data-id="'+esc(x.id)+'">保留にする</button><button type="button" data-action="reflect" data-id="'+esc(x.id)+'">この経験を振り返る</button></div>');
const prior=$("experience-plan").value;$("experience-plan").innerHTML='<option value="">関連付けずに残す</option>'+plans.map(p=>'<option value="'+esc(p.id)+'">'+esc(p.title)+'</option>').join("");if(plans.some(p=>p.id===prior))$("experience-plan").value=prior;
$("experience-list").innerHTML=list(state.experiences,"experience",x=>'<p class="meta">本人が確認して残した経験・外部未確認</p><h3>'+esc(x.actual)+'</h3><p>気づき：'+esc(x.insight||"まだ言葉にしていない")+'</p><p class="quiet">未検証：'+esc(x.unknown||"未記入")+'<br>次：'+esc(x.next||"未定")+'</p>');
$("persist").checked=state.preferences.persist;$("storage-status").textContent=state.preferences.persist?"このブラウザーに保存中。実連携やクラウド送信はありません。":"画面内だけで保持中。再読み込みで失われるため、必要ならJSONを書き出してください。";
const st=state.statements.filter(x=>x.status==="current");$("statement-list").innerHTML=st.length?st.map(t=>'<div class="memory-row"><span class="meta">'+esc(labels[t.type])+' / '+(t.confirmed?"本人が分類を確認":"分類は未確認")+'</span><p>'+esc(t.text)+'</p><button type="button" data-action="edit-message" data-id="'+esc(t.messageId)+'">内容・分類を訂正</button></div>').join(""):'<p class="empty">まだ本人の発言はありません。</p>';
$("hypothesis-list").innerHTML=state.hypotheses.length?state.hypotheses.map(h=>'<div class="memory-row"><span class="meta">模擬仮説 / '+(h.status==="withdrawn"?"取下げ済み":"未確認")+' / 根拠発言 '+h.evidenceMessageIds.length+'件</span><p>'+esc(h.label)+'</p>'+(h.status==="tentative"?'<button type="button" data-action="withdraw-hypothesis" data-id="'+esc(h.id)+'">この解釈は違う</button>':"")+'</div>').join(""):'<p class="empty">模擬仮説はまだありません。</p>';
const confirmed=state.aspirations.filter(x=>!x.deleted&&x.status==="confirmed");$("summary-list").innerHTML=confirmed.length?confirmed.map(x=>'<div class="memory-row"><p>'+esc(x.text)+'</p><a href="#aspirations">本人の言葉を変更する</a></div>').join(""):'<p class="empty">本人確認済みの要約はありません。AIによる自動確定はしません。</p>';
const deleted=["aspirations","plans","experiences"].flatMap(group=>state[group].filter(x=>x.deleted).map(x=>({group,item:x})));
let bin=$("deleted-records");if(!bin){bin=document.createElement("section");bin.id="deleted-records";bin.className="data-section";$("screen-memory").appendChild(bin);}
bin.innerHTML='<h2>削除した試作記録（復元可能）</h2>'+ (deleted.length?deleted.map(({group,item:x})=>'<div class="memory-row"><p>'+esc(x.title||x.text||x.actual)+'</p><button type="button" data-action="restore-record" data-group="'+esc(group)+'" data-id="'+esc(x.id)+'">この記録を復元</button></div>').join(""):'<p class="quiet">削除した記録はありません。</p>');
showPrediction();
}
function list(items,kind,body){const active=items.filter(x=>!x.deleted);return active.length?active.map(x=>'<article class="record" data-record="'+esc(x.id)+'">'+body(x)+'<div class="record-actions"><button type="button" data-action="edit-'+kind+'" data-id="'+esc(x.id)+'">編集する</button><button type="button" data-action="delete-'+kind+'" data-id="'+esc(x.id)+'">削除する（復元可能）</button></div></article>').join(""):'<p class="empty">まだ記録はありません。今は作らなくても大丈夫。</p>';}
function submitChat(text){if(window.WHYLive?.enabled)return window.WHYLive.submit(text);try{const r=E.reply(state,text,CASES);state=r.state;suggestion=r.suggestion;commit();$("chat-input").value="";intendedFocus=current()?.status==="ended"?"new-session":"chat-input";$("response-announcement").textContent=state.messages.filter(m=>m.role==="assistant").slice(-1)[0]?.text||"";go("dialogue");}catch(e){toast(e.message);}}
$("home-form").addEventListener("submit",e=>{e.preventDefault();const text=$("home-input").value.trim();if(text){submitChat(text);$("home-input").value="";}});
$("chat-form").addEventListener("submit",e=>{e.preventDefault();submitChat($("chat-input").value);});
document.querySelectorAll("[data-seed]").forEach(b=>b.addEventListener("click",()=>{$("home-input").value=b.dataset.seed;$("home-input").focus();}));
$("new-session").addEventListener("click",()=>{if(window.WHYLive?.enabled)return window.WHYLive.control("new");E.newSession(state);suggestion=null;commit();$("chat-input").focus();});
$("end-chat").addEventListener("click",()=>window.WHYLive?.enabled?window.WHYLive.control("end"):submitChat("今日は終わり"));
$("hold-chat").addEventListener("click",()=>window.WHYLive?.enabled?window.WHYLive.control("hold"):submitChat("今は保留"));
$("view-suggestion").addEventListener("click",()=>{if(!suggestion)return;$("plan-form").reset();$("plan-id").value="";$("plan-title").value=suggestion.title;$("plan-reason").value="";$("plan-observe").value=suggestion.observe;go("plans");toast("候補を開きました。まだ採用・保存されていません。");});
$("aspiration-form").addEventListener("submit",e=>{e.preventDefault();const text=$("aspiration-text").value.trim();if(!text)return;let item=state.aspirations.find(x=>x.id===$("aspiration-id").value);if(item){item.text=text;item.status=$("aspiration-status").value;S.log(state,item.id,"本人による訂正","aspiration");}else{item={id:S.id(),createdAt:S.now(),text,status:$("aspiration-status").value,deleted:false};state.aspirations.push(item);S.log(state,item.id,"本人が記入","aspiration");}if(pendingAspirationSource)S.log(state,item.id,"本人が会話から整理; 出典="+pendingAspirationSource,"live-aspiration-origin");pendingAspirationSource=null;e.target.reset();$("aspiration-id").value="";commit();toast("本人の言葉として残しました。");});
const planFields=["title","reason","when","where","amount","prediction","observe","stop"];
$("plan-form").addEventListener("submit",e=>{e.preventDefault();const values=Object.fromEntries(planFields.map(k=>[k,$("plan-"+k).value.trim()]));if(!values.title)return;let item=state.plans.find(x=>x.id===$("plan-id").value);if(item){Object.assign(item,values,{status:$("plan-status").value,needsReview:false});S.log(state,item.id,"本人が編集・状態を確認","plan");}else{item={id:S.id(),createdAt:S.now(),...values,status:$("plan-status").value,needsReview:false,sessionId:current()?.id||null,deleted:false};state.plans.push(item);S.log(state,item.id,"本人が状態を選択","plan");}if(pendingPlanSource)S.log(state,item.id,"本人が会話候補を選択して保存; 出典="+pendingPlanSource,"live-plan-origin");pendingPlanSource=null;e.target.reset();$("plan-id").value="";suggestion=null;commit();toast("選んだ状態で残しました。");});
const experienceFields=["actual","observed","feeling","interpretation","insight","unknown","next"];
$("experience-form").addEventListener("submit",e=>{e.preventDefault();const values=Object.fromEntries(experienceFields.map(k=>[k,$("experience-"+k).value.trim()]));if(!values.actual)return;let item=state.experiences.find(x=>x.id===$("experience-id").value);if(item)Object.assign(item,values,{planId:$("experience-plan").value||null});else{item={id:S.id(),createdAt:S.now(),...values,planId:$("experience-plan").value||null,deleted:false};state.experiences.push(item);}S.log(state,item.id,"本人の経験を保存。因果は未確定","experience");e.target.reset();$("experience-id").value="";commit();toast("経験と気づきを残しました。");});
function showPrediction(){const p=state.plans.find(x=>x.id===$("experience-plan").value);$("experience-prediction").textContent=p?"実践前の予想："+(p.prediction||"未記入"):"";}
$("experience-plan").addEventListener("change",showPrediction);
document.querySelectorAll("form").forEach(f=>f.addEventListener("reset",()=>{if(f.id==="plan-form")pendingPlanSource=null;if(f.id==="aspiration-form")pendingAspirationSource=null;f.querySelectorAll('input[type="hidden"]').forEach(x=>x.value="");}));
document.addEventListener("click",e=>{const b=e.target.closest("[data-action]");if(!b)return;const action=b.dataset.action,id=b.dataset.id;
if(action==="edit-message"){const m=state.messages.find(x=>x.id===id&&x.status==="current");if(!m)return;$("edit-message-id").value=id;$("edit-text").value=m.text;$("edit-type").value=state.statements.find(x=>x.messageId===id&&x.status==="current")?.type||"unclassified";editOrigin={action:b.dataset.action,id};$("edit-dialog").showModal();return;}
if(action==="withdraw-hypothesis"){const h=state.hypotheses.find(x=>x.id===id);if(h){h.status="withdrawn";const se=state.sessions.find(x=>x.id===h.sessionId);if(se){if(se.topicId)se.rejectedTopics.push(se.topicId);se.topicId=null;se.branchId=null;se.step=0;}suggestion=null;S.log(state,id,"本人が仮説を否定","hypothesis");commit();toast("仮説を取り下げました。");}return;}
if(action==="reflect"){go("experiences");$("experience-form").reset();$("experience-id").value="";$("experience-plan").value=id;showPrediction();return;}
if(action==="hold-plan"){const p=state.plans.find(x=>x.id===id);if(p){p.status="held";S.log(state,id,"本人が保留","plan");commit();toast("計画は消さず保留にしました。");}return;}
if(action==="restore-record"){const group=b.dataset.group;if(!["aspirations","plans","experiences"].includes(group))return;const x=state[group].find(x=>x.id===id);if(x){x.deleted=false;S.log(state,id,"削除を取消","record");commit();toast("記録を復元しました。");}return;}
const kind=action.split("-").slice(1).join("-"),group={aspiration:"aspirations",plan:"plans",experience:"experiences"}[kind];if(!group)return;const x=state[group].find(x=>x.id===id);if(!x)return;
if(action.startsWith("delete-")){x.deleted=true;S.log(state,id,"削除。記憶とデータから復元可能",kind);commit();toast("削除しました。記憶とデータから復元できます。");return;}
if(action==="edit-aspiration"){pendingAspirationSource=null;$("aspiration-id").value=id;$("aspiration-text").value=x.text;$("aspiration-status").value=x.status;go("aspirations");}
if(action==="edit-plan"){pendingPlanSource=null;$("plan-id").value=id;planFields.forEach(k=>$("plan-"+k).value=x[k]);$("plan-status").value=x.status;go("plans");}
if(action==="edit-experience"){$("experience-id").value=id;experienceFields.forEach(k=>$("experience-"+k).value=x[k]);$("experience-plan").value=x.planId||"";showPrediction();go("experiences");}
});
$("edit-dialog").addEventListener("close",()=>{const origin=editOrigin;requestAnimationFrame(()=>{const found=[...document.querySelectorAll("[data-action]")].find(b=>b.dataset.action===origin?.action&&b.dataset.id===origin?.id);(found||$("chat-input")).focus();});});
$("cancel-edit").addEventListener("click",()=>$("edit-dialog").close());
$("edit-form").addEventListener("submit",e=>{e.preventDefault();try{S.revise(state,$("edit-message-id").value,$("edit-text").value.trim(),$("edit-type").value);suggestion=null;$("edit-dialog").close();commit();toast("訂正を反映し、根拠となる仮説を取り下げました。");}catch(err){toast(err.message);}});
$("persist").addEventListener("change",()=>{state.preferences.persist=$("persist").checked;if(!state.preferences.persist){const r=window.WHYRecovery.removeBeforeReplace(storage,S.KEY);if(!r.ok){state.preferences.persist=true;$("persist").checked=true;storageError(r.error);return;}}commit();});
function exportText(){return S.serialize(state);}
$("backup-view").addEventListener("click",()=>{try{$("export-output").value=exportText();$("export-output").hidden=false;}catch(e){toast(e.message);}});
$("export-data").addEventListener("click",()=>{try{const blob=new Blob([exportText()],{type:"application/json"}),url=URL.createObjectURL(blob),a=document.createElement("a");a.href=url;a.download="SUG-WHY-prototype-"+new Date().toISOString().slice(0,10)+".json";a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);toast("WHY試作のJSONを書き出しました。外部送信はありません。");}catch(e){toast(e.message);}});
function resetPreview(){pendingImport=null;$("apply-import").disabled=true;$("import-preview").textContent="";}
$("import-text").addEventListener("input",resetPreview);
$("import-file").addEventListener("change",()=>{resetPreview();const file=$("import-file").files[0];if(!file)return;if(file.size>S.LIMIT){toast("ファイルは1MB以内にしてください。");return;}const reader=new FileReader();reader.onload=()=>{$("import-text").value=String(reader.result);preview();};reader.onerror=()=>toast("ファイルを読み取れませんでした。");reader.readAsText(file,"UTF-8");});
function preview(){try{pendingImport=S.parse($("import-text").value);$("import-preview").textContent="復元候補：会話 "+pendingImport.sessions.length+"件／発言 "+pendingImport.messages.length+"件／希望 "+pendingImport.aspirations.length+"件／計画 "+pendingImport.plans.length+"件／経験 "+pendingImport.experiences.length+"件。外部記録0件。確認後に復元します。";$("apply-import").disabled=false;}catch(e){resetPreview();$("import-preview").textContent="復元できません："+e.message;}}
$("preview-import").addEventListener("click",preview);
$("read-local").addEventListener("click",()=>{try{const text=storage().getItem(S.KEY);if(!text){toast("端末内に保存されたWHY試作データはありません。");return;}$("import-text").value=text;preview();}catch(e){toast("端末内保存を確認できません。");}});
$("apply-import").addEventListener("click",()=>{if(!pendingImport)return;const removed=window.WHYRecovery.removeBeforeReplace(storage,S.KEY);if(!removed.ok){storageError(removed.error);return;}beforeImport=S.clone(state);beforeDelete=null;state=S.clone(pendingImport);state.preferences.persist=false;suggestion=null;commit(true);$("undo-import").disabled=false;$("undo-delete").disabled=true;resetPreview();toast("確認した内容を復元しました。端末内保存は無効です。");});
$("undo-import").addEventListener("click",()=>{if(!beforeImport)return;state=beforeImport;beforeImport=null;suggestion=null;commit();toast("直前の復元を取り消しました。");});
$("stage-delete").addEventListener("click",()=>$("delete-confirm").hidden=false);
$("cancel-delete").addEventListener("click",()=>$("delete-confirm").hidden=true);
$("confirm-delete").addEventListener("click",()=>{const removed=window.WHYRecovery.removeBeforeReplace(storage,S.KEY);if(!removed.ok){storageError(removed.error);return;}beforeDelete=S.clone(state);beforeImport=null;state=S.empty();suggestion=null;pendingImport=null;$("delete-confirm").hidden=true;$("import-text").value="";$("export-output").value="";$("export-output").hidden=true;resetPreview();commit(true);$("undo-delete").disabled=false;$("undo-import").disabled=true;toast("WHY試作だけを削除しました。次の編集まで、この画面で取り消せます。");});
$("undo-delete").addEventListener("click",()=>{if(!beforeDelete)return;state=beforeDelete;beforeDelete=null;commit();toast("試作データの削除を取り消しました。");});
document.querySelectorAll("textarea").forEach(t=>{if(t.id==="home-input"||t.id==="chat-input")t.addEventListener("keydown",e=>{if(e.ctrlKey&&e.key==="Enter"){e.preventDefault();t.form.requestSubmit();}});});
["aspiration-form","plan-form","experience-form"].forEach(id=>{const f=$(id);let snapshot=null;const undo=document.createElement("button");undo.type="button";undo.textContent="戻す前の入力を復旧";undo.hidden=true;f.querySelector(".form-actions").appendChild(undo);f.addEventListener("reset",()=>{if(document.activeElement?.type!=="reset")return;snapshot=[...f.querySelectorAll("input,textarea,select")].map(x=>[x.id,x.value]);undo.hidden=false;});undo.addEventListener("click",()=>{if(snapshot)snapshot.forEach(([id,value])=>$(id).value=value);undo.hidden=true;snapshot=null;toast("戻す前の入力を復旧しました。");});f.addEventListener("submit",()=>{undo.hidden=true;snapshot=null;});});
if(variant==="curiosity"){const seeds=document.querySelector(".question-seeds");$("home-form").before(seeds);document.querySelector(".intro").textContent="「なんで？」がひとつあれば、そこから。答えを聞くだけでも、試してみてもいい。";}
window.WHYAppBridge={
state(){return S.clone(state)},
addDraft(d){state.drafts.push(window.WHYDrafts.validate(d));commit();return d.id},
changeDraft(id,fn){const d=state.drafts.find(x=>x.id===id);if(!d)return;fn(d);if(d.status==="stale"&&d.recordId){const plan=state.plans.find(p=>p.id===d.recordId);if(plan)plan.needsReview=true;}window.WHYDrafts.validate(d);commit()},
saveDraft(id,confirmed,status){const d=state.drafts.find(x=>x.id===id);if(!d)throw Error("候補がありません");const chosen=window.WHYDrafts.select(d,{confirmed,status});let r=state[{aspiration:"aspirations",plan:"plans",experience:"experiences"}[d.kind]].find(r=>r.id===d.recordId);if(r)Object.assign(r,chosen.values);else{r={id:S.id(),createdAt:S.now(),...chosen.values,deleted:false};state[{aspiration:"aspirations",plan:"plans",experience:"experiences"}[d.kind]].push(r)}if(d.kind==="aspiration")r.status="confirmed";if(d.kind==="plan")Object.assign(r,{status:chosen.status,needsReview:false,sessionId:null});if(d.kind==="experience")r.planId=r.planId||null;d.status="adopted";d.recordId=r.id;d.reviewedFields=chosen.reviewedFields;S.log(state,r.id,"会話候補を本人が確認して保存; 出典候補="+d.id,"person-confirmed-conversation-record");commit();return r.id},

records(){const blocked=new Set(state.drafts.filter(d=>d.status==="stale").map(d=>d.recordId));return state.aspirations.filter(x=>!x.deleted&&x.status==="confirmed"&&!blocked.has(x.id)).map(x=>({id:x.id,kind:'aspiration',selectedByPerson:true,provenance:'isolated-test',values:{text:x.text,status:x.status}})).concat(state.plans.filter(x=>!x.deleted&&["selected","paused","completed"].includes(x.status)&&!blocked.has(x.id)).map(x=>({id:x.id,kind:'plan',selectedByPerson:true,provenance:'isolated-test',values:Object.fromEntries(['title','reason','when','where','amount','prediction','observe','stop','status'].map(k=>[k,x[k]]))})),state.experiences.filter(x=>!x.deleted&&!blocked.has(x.id)).map(x=>({id:x.id,kind:'experience',selectedByPerson:true,provenance:'isolated-test',values:Object.fromEntries(['actual','observed','feeling','interpretation','insight','unknown','next','planId'].map(k=>[k,x[k]]))})));},
preparePlan(text,sourceId){$('plan-form').reset();$('plan-id').value='';$('plan-title').value=text.slice(0,2000);$('plan-status').value='draft';pendingPlanSource=sourceId;go('plans');toast('会話から候補を開きました。内容・理由・量を確認して保存するまで採用されません。');},
prepareAspiration(text,sourceId){$('aspiration-form').reset();$('aspiration-id').value='';$('aspiration-text').value=text.slice(0,2000);$('aspiration-status').value='exploring';pendingAspirationSource=sourceId;go('aspirations');toast('自分の言葉に編集できます。まだ本人確認済みにはしていません。');},
current(){const se=current();return{ownerId:activeOwner,revision:revisionCounter,text:document.querySelector("#screen-dialogue:not([hidden])")?$("chat-input").value:$("home-input").value,history:se?state.messages.filter(m=>m.sessionId===se.id&&m.status==="current"):[],confirmed:state.statements.filter(x=>x.confirmed&&x.status==="current").map(x=>({id:x.id,text:x.text,userConfirmed:true,status:"current"})).concat(state.aspirations.filter(x=>!x.deleted&&x.status==="confirmed").map(x=>({id:x.id,text:x.text,userConfirmed:true,status:"current"}))),hypotheses:state.hypotheses.map(x=>({id:x.id,description:x.label,evidenceMessageIds:x.evidenceMessageIds,status:x.status}))};},
switchOwner(owner){window.WHYGate.owner(owner);if(owner===activeOwner)return;const fields=[...document.querySelectorAll("#home-form textarea,#chat-form textarea,#aspiration-form input,#aspiration-form textarea,#aspiration-form select,#plan-form input,#plan-form textarea,#plan-form select,#experience-form input,#experience-form textarea,#experience-form select,#import-text,#export-output")];workspaces.set(activeOwner,{state:S.clone(state),suggestion,drafts:fields.map(x=>[x.id,x.value])});activeOwner=owner;const saved=workspaces.get(owner);state=saved?S.clone(saved.state):S.empty();suggestion=saved?.suggestion||null;if(!saved){try{const r=S.load(storage());if(r.ok&&r.state?.preferences.persist)state=r.state;else if(!r.ok)storageError(r.error);}catch(e){storageError("この利用者の保存データを読み込めません。");}}fields.forEach(x=>x.value="");["home-form","chat-form","aspiration-form","plan-form","experience-form"].forEach(id=>$(id).reset());pendingImport=null;beforeImport=null;beforeDelete=null;resetPreview();invalidateUndo();render();if(saved)saved.drafts.forEach(([id,v])=>{if($(id))$(id).value=v;});revisionCounter++;window.dispatchEvent(new CustomEvent("why-data-changed"));toast("利用者の試作領域を切り替えました。本番認証ではありません。");},
notify:toast};
["home-input","chat-input"].forEach(id=>$(id).addEventListener("input",()=>{revisionCounter++;window.dispatchEvent(new CustomEvent("why-data-changed"));}));
render();route(true);
})();
